function methodMapHtml(){return `<div class="method-map-help"><h4>Leer y explorar el mapa</h4><p><span style="color:#ba7521">●</span> <b>Naranja:</b> ubicación propuesta con referencia geográfica. <span style="color:#7850a5">◆ ?</span> <b>Morado:</b> localización por confirmar; consulta la duda documentada. <span style="color:#21786a">●</span> <b>Verde:</b> correspondencia confirmada por una persona identificada.</p><p>Usa la rueda o los botones +/− para acercar; arrastra para desplazarte. Puedes ampliar el mapa, buscar un lugar, filtrar por estado y volver a encuadrar todos los puntos. Al seleccionar un punto se abre su ficha: desde allí accedes a las páginas y sus transcripciones.</p><p>Las coordenadas y la cartografía se consultan desde archivos locales. Las referencias enlazan a sus fuentes públicas y requieren conexión si decides abrirlas. GeoJSON exporta los lugares visibles con estado, notas y referencias documentales. Para ríos, costas o zonas extensas, un punto de referencia no representa sus límites.</p></div>`}
function methodSemanticHtml() {
 return `<details class="method-semantic"><summary>¿Cómo podremos usar los embeddings?</summary><p><b>Ya disponible:</b> índice local y actualización incremental. Las siguientes consultas aún requieren integración en el buscador.</p><div class="method-semantic-grid">${[
 ['Buscar por significado','Consultar «viajes por río» y recuperar pasajes relacionados aunque empleen palabras distintas.'],
 ['Encontrar páginas relacionadas','Partir de una página útil y proponer otras parecidas, conservando archivo, página y versión.'],
 ['Explorar temas y similitudes','Agrupar pasajes o dibujar un mapa de semejanzas para explorar el corpus. Los grupos necesitan interpretación humana.'],
 ['Preparar nuevas preguntas','Sugerir candidatas para que el usuario las compruebe y seleccione antes de usar la matriz IA.']
 ].map(([title,text])=>`<article><h4>${title}</h4><p>${text}</p></article>`).join('')}</div><h4>Aplicarlo a relaciones entre personas, familias y lugares</h4><ol><li><b>Partir de evidencia textual:</b> nombres y variantes del catálogo permiten ubicar candidatas. Un apellido compartido no demuestra parentesco.</li><li><b>Ampliar por significado:</b> buscar pasajes sobre residencia, parentesco, viajes, trabajo o intercambio, o usar una página relevante como ejemplo. Combinar la similitud con las menciones del catálogo.</li><li><b>Preguntar sobre la selección:</b> en la matriz IA, preguntar quién se relaciona con quién o con qué lugar, de qué manera, cuándo y qué cita lo respalda. Registrar también cuando el texto no lo dice.</li><li><b>Corroborar y registrar:</b> distinguir menciones en una misma página, relaciones expresadas en el texto y relaciones comprobadas por una persona contra la imagen.</li></ol><p><b>Analítica propuesta:</b> el piloto Microsoft GraphRAG explora relaciones tipificadas entre personas, familias, lugares, instituciones y tiempo. Sus enlaces permiten consultar citas, carpeta, documento, página y lectura del piloto. Se limita a 30 páginas y requiere revisar las interpretaciones del modelo. La búsqueda semántica general y la comparación temporal de todo el corpus siguen pendientes de integración.</p><p>La similitud semántica sirve para ordenar candidatas: no confirma identidades, fechas ni relaciones históricas. Los nombres completos mantienen su comprobación textual y de cercanía. La matriz y los cruces actuales sí están disponibles.</p></details>`;
}
function methodLayoutHtml() {
 return `<div class="method-layout-note"><h4>¿Qué hicimos con páginas dobles o con dos columnas?</h4><p><b>En el lote principal:</b> una página PDF se convirtió en una sola imagen. Si contenía dos hojas escaneadas o dos columnas, se enviaron juntas a Qwen con la instrucción de seguir el orden de lectura. No hubo detección ni separación automática de hojas o columnas.</p><p><b>En las pruebas por regiones:</b> se exploraron recortes y, después, franjas horizontales solapadas con Qwen 27B. Estos ensayos quedaron incompletos y no constituyen un método general para separar columnas.</p><p><b>Qué implica:</b> los contadores y las referencias identifican páginas PDF, no hojas físicas. Un cruce puede reunir menciones de dos escaneos contenidos en una misma página. Hay que comprobar omisiones y orden de lectura en la imagen.</p><p><b>Mejora pendiente:</b> identificar y revisar regiones izquierda/derecha o columnas, fijar su orden y guardar coordenadas vinculadas a la página original antes de una nueva transcripción.</p></div>`;
}
function methodSecondHtml() {
 return `<div class="method-second"><h4>Qué probamos y qué aprendimos</h4><p>El objetivo fue obtener alternativas para revisar páginas difíciles, no reemplazar la revisión humana ni volver a procesar todo el corpus.</p><div class="method-second-history"></div><div class="method-content"><article><h4>Para qué sirve hoy</h4><p>En el banco, las páginas con una segunda lectura disponible permiten comparar imagen, 9B y 27B. Se puede usar una lectura como borrador, corregirla y después guardar la decisión humana.</p></article><article><h4>Qué falta comprobar</h4><p>El piloto no fue una muestra aleatoria. Desaparecer una alerta no demuestra que se haya recuperado todo el texto. Cambiaron el modelo, el prompt y, en el segundo ensayo, los recortes.</p></article><article><h4>Cómo podría continuar</h4><p>Aplicar nuevas lecturas sólo a casos seleccionados y medir su fidelidad con revisión humana. La configuración 27B instalada no cabe con la reserva exigida por la política actual de inferencia íntegra en GPU; requiere un modelo compatible antes de repetirla. No hay reintento automático.</p></article></div></div>`;
}
const methodSecondRecords=new Map();
function methodSecondRefresh() {
 const host=methodSection.querySelector('.method-second-history');if(!host)return;
 const runs=studyData?.runs.filter(r=>r.stage==='second_reading')||[],signature=JSON.stringify(runs);
 if(host.dataset.signature===signature)return;host.dataset.signature=signature;
 const findings={pilot_01:['Piloto con la página completa','Tres páginas elegidas por alertas. En dos desaparecieron las alertas automáticas; una siguió terminando por límite. La exactitud no fue evaluada.'],all_flagged_01:['Intento posterior por regiones','Se planificaron 15 páginas y se guardaron dos antes del fallo. Las franjas superior e inferior se solaparon; los casos truncados se subdividieron. Las dos salidas requieren comprobar las uniones. El registro conserva un timeout de solicitud y otro del monitor NVIDIA.']};
 host.innerHTML=runs.map(r=>`<article><span class="method-real-label">${esc(findings[r.run_id]?.[0]||'Ejecución registrada')}</span><h5>${esc(r.model||'Modelo no registrado')}</h5><p><b>${r.processed??'—'} / ${r.total??'—'} páginas · ${r.elapsed_seconds==null?'Tiempo no registrado':emTime(r.elapsed_seconds)}</b><br>${esc(studyStatus(r.status))}</p><p>${esc(findings[r.run_id]?.[1]||'Consulta el registro para interpretar el alcance de esta ejecución.')}</p><button type="button" data-method-run="${esc(r.run_id)}">Ver esta ejecución y su telemetría →</button><details data-method-second-record="${esc(r.run_id)}"><summary>Ver configuración y prompt de este ensayo</summary><div class="method-second-config">Al abrir, se consulta el registro guardado.</div></details></article>`).join('')||'<p>No hay ensayos registrados disponibles.</p>';
}
async function methodSecondRecord(details) {
 const id=details.dataset.methodSecondRecord,host=details.querySelector('.method-second-config');if(!id||!host||host.dataset.loaded)return;
 host.textContent='Consultando el registro guardado…';
 try{
  let record=methodSecondRecords.get(id);
  if(!record){const response=await fetch('/process-telemetry/record?stage=second_reading&run='+encodeURIComponent(id),{cache:'no-store'});if(!response.ok)throw Error();record=await response.json();methodSecondRecords.set(id,record)}
  const m=record.manifest,command=m.command||[],arg=flag=>{const i=command.indexOf(flag);return i<0?'No registrado':command[i+1]},layers=arg('-ngl');
  host.innerHTML=`<p>Modelo registrado: <b>${esc(m.model)}</b>. Motor local: llama.cpp. Contexto: ${esc(arg('-c'))} tokens; presupuesto visual: ${esc(arg('--image-max-tokens'))} tokens; capas solicitadas en GPU: ${esc(layers)}.</p><p>Estos son parámetros históricos del ensayo. La política actual exige todas las capas del modelo en GPU.</p><p>Prompt base exacto conservado:</p><pre class="prompt-box"></pre>${id==='all_flagged_01'?'<p>En cada región se añadió una instrucción para leer sólo ese recorte, sin inferir contenido fuera de sus bordes. Los prompts de cada recorte se conservan en el paquete descargable.</p>':''}<a href="/process-telemetry/bundle?stage=second_reading&run=${encodeURIComponent(id)}" download>Descargar registro y resultados del ensayo ↓</a>`;
  host.querySelector('pre').textContent=m.prompt||'Prompt no registrado';host.dataset.loaded='true';
 }catch{host.textContent='No se pudo cargar el registro. Cierra y abre este apartado para volver a consultar.'}
}
