function methodDraw() {
 const key=methodSelected,parts=processMethods[key],s=methodStory[key],i=studyStages.indexOf(key);
 for(const b of methodSection.querySelectorAll('[data-method]')) {const selected=b.dataset.method===key;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;}
 const panel=methodSection.querySelector('#method-panel');panel.setAttribute('aria-labelledby',`method-tab-${key}`);
 panel.innerHTML=`<div class="method-main"><figure class="method-scene"><span>ESQUEMA ILUSTRATIVO</span>${methodArt(key)}<figcaption>${s[3]}</figcaption></figure><div class="method-story"><span class="method-kicker">${i>=0?`ETAPA ${String(i+1).padStart(2,'0')} / ${studyStages.length}`:'APLICAR A TU INVESTIGACIÓN'} · ${esc(methodName(key))}</span><h3>${s[0]}</h3><p>${s[1]}</p><ol>${s[2].map((line,j)=>`<li><span aria-hidden="true">${j+1}</span>${line}</li>`).join('')}</ol></div></div>
 <div class="method-content">${['Qué recibimos','Qué hicimos y con qué lógica','Qué quedó registrado'].map((label,i)=>`<article><h4>${label}</h4><p>${parts[i]}</p></article>`).join('')}</div>
 <div class="method-interpret"><strong>Cómo interpretar esta etapa</strong><p>${parts[3]}</p></div>
 ${key==='embeddings'?methodSemanticHtml():''}
 ${key==='rendering'?methodLayoutHtml():''}
 ${key==='second_reading'?methodSecondHtml():''}
 ${key==='map'?methodMapHtml():''}
 <div class="method-facts">${methodMetricHtml()}</div>
 <div class="method-support-slot"></div>
 <div class="method-links">${studyStages.includes(key)?'<button type="button" data-method-metrics>Ver registros y telemetría →</button>':''}<button type="button" data-method-open>${key==='embeddings'?'Ver estado del índice':'Abrir '+s[4]} →</button><button type="button" data-method-summary>Ver consolidado de todas las etapas ↓</button></div>`;
 methodMountSupport(key);methodSecondRefresh();
 if(key==='map')methodMapRefresh();
 const details=panel.querySelector('.method-semantic');if(details){details.open=methodOpenDetails.has(key);details.ontoggle=()=>{if(details.open){methodOpenDetails.add(key);methodStop()}else methodOpenDetails.delete(key)}}
 methodSection.querySelector('[data-method-prev]').disabled=methodKeys.indexOf(key)===0;
 methodSection.querySelector('[data-method-next]').disabled=methodKeys.indexOf(key)===methodKeys.length-1;
 methodSection.querySelector('[data-method-position]').textContent=`${methodKeys.indexOf(key)+1} de ${methodKeys.length} · ${methodName(key)}`;
}
function methodSet(key,{manual=true,focus=false}={}) {
 if(!methodKeys.includes(key))return;
 if(manual)methodStop();methodSelected=key;methodDraw();
 if(focus)methodSection.querySelector(`[data-method="${key}"]`).focus({preventScroll:true});
}
function methodStop(){clearTimeout(methodTimer);methodTimer=null;methodPlaying=false;methodControls()}
function methodControls(){
 const play=methodSection.querySelector('[data-method-play]');play.textContent=methodPlaying?'Ⅱ Pausar recorrido':'▷ Reproducir recorrido';play.setAttribute('aria-pressed',String(methodPlaying));
 const motion=methodSection.querySelector('[data-method-motion]');motion.textContent=methodAnimations?'Pausar animaciones':'Activar animaciones';motion.setAttribute('aria-pressed',String(methodAnimations));motion.disabled=methodMotion.matches;if(methodMotion.matches)motion.textContent='Movimiento reducido';
 methodSection.classList.toggle('method-still',!methodAnimations);
}
function methodSchedule(){
 clearTimeout(methodTimer);
 methodTimer=setTimeout(()=>{if(!methodPlaying)return;const next=methodKeys.indexOf(methodSelected)+1;if(next>=methodKeys.length){methodStop();return}methodSet(methodKeys[next],{manual:false});methodSchedule()},12000);
}
function methodShowMetrics(){methodStop();studySelect(methodSelected);study.querySelector('.study-tabs').scrollIntoView({behavior:methodMotion.matches?'auto':'smooth',block:'start'})}
methodSection.addEventListener('click',event=>{
 const target=event.target.closest('button');if(!target)return;
 if(target.dataset.method){methodSet(target.dataset.method,{focus:true});return}
 if(target.dataset.methodWork){methodStop();showView(target.dataset.methodWork);window.scrollTo({top:0,behavior:methodMotion.matches?'auto':'smooth'});return}
 if(target.dataset.methodHelp){methodOpenHelp(target.dataset.methodHelp);return}
 if(target.dataset.methodRun){studySelection.second_reading=target.dataset.methodRun;methodSelected='second_reading';methodShowMetrics();return}
 if(target.hasAttribute('data-method-play')){if(methodPlaying)methodStop();else {methodPlaying=true;if(methodSelected===methodKeys.at(-1))methodSet(methodKeys[0],{manual:false});methodControls();methodSchedule()}return}
 if(target.hasAttribute('data-method-motion')){methodAnimations=!methodAnimations;methodControls();return}
 if(target.hasAttribute('data-method-prev')||target.hasAttribute('data-method-next')){methodSet(methodKeys[methodKeys.indexOf(methodSelected)+(target.hasAttribute('data-method-next')?1:-1)]);return}
 if(target.hasAttribute('data-method-metrics')){methodShowMetrics();return}
 if(target.hasAttribute('data-method-summary')){methodStop();study.querySelector('.study-consolidated').scrollIntoView({behavior:methodMotion.matches?'auto':'smooth',block:'start'});return}
 if(target.hasAttribute('data-method-open')){
  if(methodSelected==='map'){methodStop();priorityMode='map';prioritySelected='';showView('analysis');prioritySyncURL('analysis');if(priorityResult)priorityDraw();document.getElementById('priority-results')?.scrollIntoView({behavior:methodMotion.matches?'auto':'smooth',block:'start'});return}
  methodStop();const destinations={inventory:'sources',rendering:'results',transcription:'results',second_reading:'results',human:'results',cross_analysis:'analysis',matrix:'selection',graphrag:'graphrag',graph_query:'graphrag',search:'search',selection:'selection',export:'selection'};
  if(destinations[methodSelected]){showView(destinations[methodSelected]);window.scrollTo({top:0,behavior:methodMotion.matches?'auto':'smooth'})}
  else if(['embeddings','graphrag'].includes(methodSelected))methodShowMetrics();
  else {studySelect('pages');study.querySelector('.study-tabs').scrollIntoView({behavior:methodMotion.matches?'auto':'smooth',block:'start'})}
 }
});
methodSection.addEventListener('toggle',event=>{if(event.target.open){methodStop();if(event.target.dataset.methodSecondRecord)methodSecondRecord(event.target)}},true);
methodSection.querySelector('.method-nav').addEventListener('keydown',event=>{
 if(!event.target.matches('[data-method]')||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
 event.preventDefault();const i=methodKeys.indexOf(methodSelected),next=event.key==='Home'?0:event.key==='End'?methodKeys.length-1:(i+(event.key==='ArrowRight'?1:-1)+methodKeys.length)%methodKeys.length;
 methodSet(methodKeys[next],{focus:true});
});
document.addEventListener('visibilitychange',()=>{if(document.hidden)methodStop()});
methodMotion.addEventListener('change',event=>{methodAnimations=!event.matches;methodStop()});
new IntersectionObserver(entries=>{const visible=entries.some(entry=>entry.isIntersecting);methodSection.classList.toggle('method-offscreen',!visible);if(!visible)methodStop()}).observe(methodSection);
const methodSelect=studySelect;studySelect=function(stage){if(studyStages.includes(stage))methodSet(stage);return methodSelect(stage)};
const methodStudyDraw=studyDraw;studyDraw=function(){methodStudyDraw();const facts=methodSection.querySelector('.method-facts');if(facts)facts.innerHTML=methodMetricHtml();methodSecondRefresh()};
const methodShowView=showView;showView=function(name){if(name==='technology'){const result=methodShowView('overview');methodOpenHelp('hardware');return result}if(name!=='overview')methodStop();return methodShowView(name)};
